// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/instance-backup-settings", wrapper.GetInstanceBackupSettings)
	router.PUT(options.BaseURL+"/instance-backup-settings", wrapper.UpdateInstanceBackupSettings)
	router.GET(options.BaseURL+"/instance-backup-statuses", wrapper.GetInstanceBackupStatus)
	router.GET(options.BaseURL+"/instance-backup-destinations", wrapper.ListInstanceBackupDestinations)
	router.GET(options.BaseURL+"/instance-backups", wrapper.ListInstanceBackups)
	router.POST(options.BaseURL+"/instance-backups", wrapper.StartInstanceBackup)
	router.GET(options.BaseURL+"/instance-backups/:instanceBackupId", wrapper.GetInstanceBackup)
	router.POST(options.BaseURL+"/instance-backups/:instanceBackupId/download-tokens", wrapper.CreateInstanceBackupDownloadToken)
	router.GET(options.BaseURL+"/instance-backup-downloads", wrapper.DownloadInstanceBackup)
	router.POST(options.BaseURL+"/master-key-confirmations", wrapper.RequestMasterKeyConfirmation)
	router.POST(options.BaseURL+"/master-key-exports", wrapper.CreateMasterKeyExport)
	router.GET(options.BaseURL+"/master-key-downloads", wrapper.DownloadMasterKey)
	router.PUT(options.BaseURL+"/master-key-acknowledgments", wrapper.AcknowledgeMasterKey)
	router.POST(options.BaseURL+"/instance-recoveries", wrapper.CreateInstanceRecovery)
	router.GET(options.BaseURL+"/instance-recoveries/:instanceRecoveryId", wrapper.GetInstanceRecovery)
	router.POST(options.BaseURL+"/instance-recoveries/:instanceRecoveryId/confirmations", wrapper.RequestInstanceRecoveryConfirmation)
	router.POST(options.BaseURL+"/instance-recoveries/:instanceRecoveryId/apply", wrapper.ApplyInstanceRecovery)
	router.POST(options.BaseURL+"/instance-recoveries/:instanceRecoveryId/cancel", wrapper.CancelInstanceRecovery)
	router.POST(options.BaseURL+"/instance-recoveries/:instanceRecoveryId/activate", wrapper.ActivateInstanceRecovery)
}

