// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListInstanceBackupDestinations List the storages root admin can select as destinations
	// (GET /instance-backup-destinations)
	ListInstanceBackupDestinations(ctx context.Context, request ListInstanceBackupDestinationsRequestObject) (ListInstanceBackupDestinationsResponseObject, error)
	// DownloadInstanceBackup Download the encrypted file of a Databasus backup copy
	// (GET /instance-backup-downloads)
	DownloadInstanceBackup(ctx context.Context, request DownloadInstanceBackupRequestObject) (DownloadInstanceBackupResponseObject, error)
	// GetInstanceBackupSettings Get the Databasus backup settings
	// (GET /instance-backup-settings)
	GetInstanceBackupSettings(ctx context.Context, request GetInstanceBackupSettingsRequestObject) (GetInstanceBackupSettingsResponseObject, error)
	// UpdateInstanceBackupSettings Replace the Databasus backup settings
	// (PUT /instance-backup-settings)
	UpdateInstanceBackupSettings(ctx context.Context, request UpdateInstanceBackupSettingsRequestObject) (UpdateInstanceBackupSettingsResponseObject, error)
	// GetInstanceBackupStatus Get the protection state of the instance
	// (GET /instance-backup-statuses)
	GetInstanceBackupStatus(ctx context.Context, request GetInstanceBackupStatusRequestObject) (GetInstanceBackupStatusResponseObject, error)
	// ListInstanceBackups List the Databasus backups
	// (GET /instance-backups)
	ListInstanceBackups(ctx context.Context, request ListInstanceBackupsRequestObject) (ListInstanceBackupsResponseObject, error)
	// StartInstanceBackup Start a Databasus backup now
	// (POST /instance-backups)
	StartInstanceBackup(ctx context.Context, request StartInstanceBackupRequestObject) (StartInstanceBackupResponseObject, error)
	// GetInstanceBackup Get a Databasus backup with the outcome of each copy
	// (GET /instance-backups/{instanceBackupId})
	GetInstanceBackup(ctx context.Context, request GetInstanceBackupRequestObject) (GetInstanceBackupResponseObject, error)
	// CreateInstanceBackupDownloadToken Issue a single-use token to download a stored copy
	// (POST /instance-backups/{instanceBackupId}/download-tokens)
	CreateInstanceBackupDownloadToken(ctx context.Context, request CreateInstanceBackupDownloadTokenRequestObject) (CreateInstanceBackupDownloadTokenResponseObject, error)
	// CreateInstanceRecovery Upload a Databasus backup file and its master key to prepare a replacement
	// (POST /instance-recoveries)
	CreateInstanceRecovery(ctx context.Context, request CreateInstanceRecoveryRequestObject) (CreateInstanceRecoveryResponseObject, error)
	// GetInstanceRecovery Get a recovery from the local recovery journal
	// (GET /instance-recoveries/{instanceRecoveryId})
	GetInstanceRecovery(ctx context.Context, request GetInstanceRecoveryRequestObject) (GetInstanceRecoveryResponseObject, error)
	// ActivateInstanceRecovery Confirm the old instance is stopped and end the recovery pause
	// (POST /instance-recoveries/{instanceRecoveryId}/activate)
	ActivateInstanceRecovery(ctx context.Context, request ActivateInstanceRecoveryRequestObject) (ActivateInstanceRecoveryResponseObject, error)
	// ApplyInstanceRecovery Replace this installation with the prepared recovery
	// (POST /instance-recoveries/{instanceRecoveryId}/apply)
	ApplyInstanceRecovery(ctx context.Context, request ApplyInstanceRecoveryRequestObject) (ApplyInstanceRecoveryResponseObject, error)
	// CancelInstanceRecovery Cancel a recovery that was not applied
	// (POST /instance-recoveries/{instanceRecoveryId}/cancel)
	CancelInstanceRecovery(ctx context.Context, request CancelInstanceRecoveryRequestObject) (CancelInstanceRecoveryResponseObject, error)
	// RequestInstanceRecoveryConfirmation Email root admin a code that confirms applying this recovery
	// (POST /instance-recoveries/{instanceRecoveryId}/confirmations)
	RequestInstanceRecoveryConfirmation(ctx context.Context, request RequestInstanceRecoveryConfirmationRequestObject) (RequestInstanceRecoveryConfirmationResponseObject, error)
	// AcknowledgeMasterKey Record that root admin saved the current master key
	// (PUT /master-key-acknowledgments)
	AcknowledgeMasterKey(ctx context.Context, request AcknowledgeMasterKeyRequestObject) (AcknowledgeMasterKeyResponseObject, error)
	// RequestMasterKeyConfirmation Email root admin a code that confirms a master-key export
	// (POST /master-key-confirmations)
	RequestMasterKeyConfirmation(ctx context.Context, request RequestMasterKeyConfirmationRequestObject) (RequestMasterKeyConfirmationResponseObject, error)
	// DownloadMasterKey Download the master key once
	// (GET /master-key-downloads)
	DownloadMasterKey(ctx context.Context, request DownloadMasterKeyRequestObject) (DownloadMasterKeyResponseObject, error)
	// CreateMasterKeyExport Get a single-use token that downloads the master key
	// (POST /master-key-exports)
	CreateMasterKeyExport(ctx context.Context, request CreateMasterKeyExportRequestObject) (CreateMasterKeyExportResponseObject, error)
}

type StrictHandlerFunc func(ctx *gin.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictGinServerOptions struct {
	// RequestErrorHandlerFunc is called when a request cannot be parsed or
	// decoded. It is invoked for JSON bind failures, form parse/bind errors,
	// multipart reader errors, media type parse errors, missing multipart
	// boundaries, and request body read errors. The default returns 400.
	RequestErrorHandlerFunc func(ctx *gin.Context, err error)
	// HandlerErrorFunc is called when the application handler (or any
	// middleware wrapping it) returns a non-nil error. The default returns 500.
	HandlerErrorFunc func(ctx *gin.Context, err error)
	// ResponseErrorHandlerFunc is called when the response object fails to
	// serialize (Visit*Response returns an error) or when the handler returns
	// an unexpected response type. The default returns 500.
	ResponseErrorHandlerFunc func(ctx *gin.Context, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictGinServerOptions{
		RequestErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		},
		HandlerErrorFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
		ResponseErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictGinServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		}
	}
	if options.HandlerErrorFunc == nil {
		options.HandlerErrorFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictGinServerOptions
}

